-- mod-retail-achievements: retail's mount achievements, pointed at WotLK content. Generated by
-- tools/build_achievements.py from data/achievements.tsv, data/criteria.tsv and data/letters.tsv:
-- change those files and run the tool again, don't edit this one.
-- Achievements 9300-9799, criteria 20000-23999. The client has the same rows in the spell patch.

DELETE FROM `achievement_reward` WHERE `ID` BETWEEN 9300 AND 9799;
DELETE FROM `achievement_criteria_data` WHERE `criteria_id` BETWEEN 20000 AND 23999;
DELETE FROM `achievement_criteria_dbc` WHERE `ID` BETWEEN 20000 AND 23999;
DELETE FROM `achievement_dbc` WHERE `ID` BETWEEN 9300 AND 9799;
DELETE FROM `player_factionchange_achievement` WHERE `alliance_id` BETWEEN 9300 AND 9799;


-- Criteria the core only counts with a row here (kills, battleground wins), and class checks.

-- A character that changes faction swaps each Alliance achievement for its Horde twin and back.

