INSERT INTO `achievement_reward` (`ID`, `TitleA`, `TitleH`, `ItemID`, `Sender`, `Subject`, `Body`, `MailTemplateID`) VALUES
(9300, 0, 0, 400521, 32216, 'We\'re Going to Need More Saddles', '$N,$B$BYour stables keep growing, and so does my respect for you. I raised this Jade Pandaren Kite myself, and it has been waiting for a rider who knows how to look after a herd. It\'s yours now.$B$BYours,$BMei', 0),
